class TFMLogicStepOperatorClassifyInput extends TFMLogicBlock implements TFMLogicStepOperatorInterface, TFMLogicStepOperatorVariableContextLookupInterface
{
    TFMFlowVariableName variableName;
    TFMFlowContextField contextField;

}

Method.Source:
[TFMParameter('',"@TFM:Storeresultinvariable")]
public TFMFlowVariableName parmVariableName(TFMFlowVariableName _variableName = variableName)
{
    variableName = _variableName;
    return variableName;
}

[TFMParameter('', "@TFM:Whichfieldtoclassifyfrom")]
public TFMFlowContextField parmContextField(TFMFlowContextField _contextField = contextField)
{
    contextField = _contextField;
    return contextField;
}

public str runLogic ( TFMRequestElement _request )
{

    str                 fieldValue = _request.getFieldValue(contextField);
    TFMClassificationID classificationID = TFMClassificationHierarchy::classifyInput(fieldValue);
    _request.logicContext().addFieldContent(variableName, classificationID);
    _request.makeLogEntry (strFmt('Classified %1 as %2 and stored it in %3', contextField, classificationID, variableName));
    return '';
}

public Map lookupVariableContext()
{
    Map                             result = new Map(Types::String, Types::String);
    Query                           query                   = new Query();
    QueryBuildDataSource            queryBuildDataSource;
    TFMClassificationHierarchy      classHierarchy;
    QueryRun                        qr;
    queryBuildDataSource = query.addDataSource(tablenum(TFMClassificationHierarchy));

    qr = new QueryRun(query);

    while (qr.next())
    {
        classHierarchy = qr.get(tablenum(TFMClassificationHierarchy));
        result.insert(classHierarchy.ClassificationID, classHierarchy.ClassificationID);
    }
    return result;
}
